 for(int i=lid;i<SLOTS*DIM;i+=ATTN_LOCAL) {
  int slot=i/DIM,r=row+slot/2,h=kv*2+slot%2;q[i]=r<active?query[(h*ROWS+r)*DIM+i%DIM]:0;
 }
 barrier(CLK_LOCAL_MEM_FENCE);
 float max0=-INFINITY;float max1=-INFINITY;float max2=-INFINITY;float max3=-INFINITY;
 for(int t=lid;t<last;t+=ATTN_LOCAL) {
  float4 dot0=(float4)0;float4 dot1=(float4)0;float4 dot2=(float4)0;float4 dot3=(float4)0;
  for(int c=0;c<DIM;c+=4) {
   float4 k=vload_half4(0,cache+(kv*CONTEXT+t)*DIM+c);
   dot0=fma(vload4(0,q+0*DIM+c),k,dot0);dot1=fma(vload4(0,q+1*DIM+c),k,dot1);dot2=fma(vload4(0,q+2*DIM+c),k,dot2);dot3=fma(vload4(0,q+3*DIM+c),k,dot3);
  }
  float score0=t<used[0]?(((dot0.s0+dot0.s1)+dot0.s2)+dot0.s3)*0x1.6a09e667f3bccp-4f:-INFINITY;p[0*MAX_KEYS+t]=score0;max0=fmax(max0,score0);float score1=t<used[1]?(((dot1.s0+dot1.s1)+dot1.s2)+dot1.s3)*0x1.6a09e667f3bccp-4f:-INFINITY;p[1*MAX_KEYS+t]=score1;max1=fmax(max1,score1);float score2=t<used[2]?(((dot2.s0+dot2.s1)+dot2.s2)+dot2.s3)*0x1.6a09e667f3bccp-4f:-INFINITY;p[2*MAX_KEYS+t]=score2;max2=fmax(max2,score2);float score3=t<used[3]?(((dot3.s0+dot3.s1)+dot3.s2)+dot3.s3)*0x1.6a09e667f3bccp-4f:-INFINITY;p[3*MAX_KEYS+t]=score3;max3=fmax(max3,score3);
 }
 scratch[0*ATTN_LOCAL+lid]=max0;scratch[1*ATTN_LOCAL+lid]=max1;scratch[2*ATTN_LOCAL+lid]=max2;scratch[3*ATTN_LOCAL+lid]=max3;
 barrier(CLK_LOCAL_MEM_FENCE);
 for(int step=ATTN_LOCAL/2;step>0;step/=2) {
  if(lid<step)for(int h=0;h<SLOTS;h++)scratch[h*ATTN_LOCAL+lid]=fmax(scratch[h*ATTN_LOCAL+lid],scratch[h*ATTN_LOCAL+lid+step]);
  barrier(CLK_LOCAL_MEM_FENCE);
 }
 if(lid<SLOTS)maximum[lid]=scratch[lid*ATTN_LOCAL];
 barrier(CLK_LOCAL_MEM_FENCE);
 for(int h=0;h<SLOTS;h++)for(int t=lid*4;t<used[h];t+=ATTN_LOCAL*4) {
  if(t+3<used[h])vstore4(poly_exp2((vload4(0,p+h*MAX_KEYS+t)-(float4)maximum[h])*(float4)1.4426950216293335f),0,p+h*MAX_KEYS+t);
  else for(int j=t;j<used[h];j++)p[h*MAX_KEYS+j]=exp(p[h*MAX_KEYS+j]-maximum[h]);
 }
