 barrier(CLK_LOCAL_MEM_FENCE);
 for(int h=0;h<SLOTS;h++)for(int t=lid*4;t<used[h];t+=ATTN_LOCAL*4) {
  if(t+3<used[h])vstore4(vload4(0,p+h*MAX_KEYS+t)/(float4)denominator[h],0,p+h*MAX_KEYS+t);
  else for(int j=t;j<used[h];j++)p[h*MAX_KEYS+j]/=denominator[h];
 }
 barrier(CLK_LOCAL_MEM_FENCE);
