  float4 pv0=(float4)0;float4 pv1=(float4)0;float4 pv2=(float4)0;float4 pv3=(float4)0;
  for(int t=0;t<last;t++) {
   float4 v=vload_half4(0,cache+(8*CONTEXT+kv*CONTEXT+t)*DIM+c);
